function rr(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function draw(){ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,W,H);const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#101d23');sky.addColorStop(.58,'#172322');sky.addColorStop(1,'#080d10');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
 // distant dead-city silhouettes
 for(let layer=0;layer<3;layer++){const f=[.12,.25,.48][layer],base=[345,390,444][layer];ctx.fillStyle=['#142025','#111b1e','#101719'][layer];for(let i=-1;i<13;i++){let x=i*112-(camera*f%112),h=55+((i*37+layer*61)%125);ctx.fillRect(x,base-h,75+((i*23)%40),h);ctx.fillStyle='#21302d';for(let j=0;j<4;j++){let wy=base-h+14+j*19;if(wy<base-4){ctx.fillStyle=((i+j+layer)%4===0)?'#96463e':'#33423b';ctx.fillRect(x+10+j%2*20,wy,4,7)}}ctx.fillStyle=['#142025','#111b1e','#101719'][layer]}}
 // light shafts behind city
 ctx.save();ctx.globalAlpha=.11;for(let i=0;i<4;i++){let x=(i*280-camera*.18%280);ctx.fillStyle=i%2?'#b8d389':'#ff6053';ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x+85,0);ctx.lineTo(x-20,450);ctx.lineTo(x-100,450);ctx.fill()}ctx.restore();
 // local world
 ctx.save();let jx=shake?rand(-shake,shake):0,jy=shake?rand(-shake,shake):0;ctx.translate(-camera+jx,jy);
 // overhead conduits and hanging lamps
 for(let x=Math.floor(camera/180)*180;x<camera+W+180;x+=180){ctx.fillStyle='#273332';ctx.fillRect(x,42,3,118);ctx.fillStyle='#33453e';ctx.fillRect(x-13,143,30,7);ctx.fillStyle='#ff6252';ctx.globalAlpha=.65+Math.sin(tick*3+x)*.2;ctx.fillRect(x-3,152,8,2);ctx.globalAlpha=1;ctx.fillStyle='#273432';ctx.fillRect(x-20,20,45,7);ctx.fillRect(x-18,27,3,30)}
 // floor and platform geometry
 for(const q of platforms){ctx.fillStyle='#121b1c';ctx.fillRect(q.x,q.y,q.w,q.h);ctx.fillStyle='#48564b';ctx.fillRect(q.x,q.y,q.w,5);ctx.fillStyle='#202a27';ctx.fillRect(q.x,q.y+5,q.w,3);ctx.fillStyle='#29352e';for(let x=q.x+15;x<q.x+q.w-8;x+=36){ctx.fillRect(x,q.y+16,2,Math.max(4,q.h-19));ctx.fillStyle='#3b493c';ctx.fillRect(x+8,q.y+9,4,2);ctx.fillStyle='#29352e'}if(q.h>35){ctx.fillStyle='#1b2826';for(let x=q.x+20;x<q.x+q.w;x+=66){ctx.fillRect(x,q.y+28,28,2);ctx.fillStyle='#3c4b3b';ctx.fillRect(x+3,q.y+24,3,4);ctx.fillStyle='#1b2826'}}}
 // hazardous gaps: dark abyss glow
 for(const x of [490,720,960,1255,1485,1705,2005,2245,2490,2750,2990,3270]){ctx.fillStyle='#080d11';ctx.fillRect(x,461,75,90);ctx.fillStyle='#571e26';ctx.globalAlpha=.4+Math.sin(tick*4+x)*.2;ctx.fillRect(x+12,480,3,50);ctx.globalAlpha=1}
 // signal nodes
 for(const n of nodes){if(n.got){ctx.globalAlpha=.26;ctx.fillStyle='#d4ff48';ctx.beginPath();ctx.arc(n.x,n.y,19,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;continue}ctx.save();ctx.translate(n.x,n.y+Math.sin(tick*2+n.x)*5);ctx.rotate(tick*.5);ctx.strokeStyle='#d4ff48';ctx.lineWidth=2;ctx.shadowBlur=16;ctx.shadowColor='#d4ff48';ctx.beginPath();ctx.moveTo(0,-16);ctx.lineTo(13,0);ctx.lineTo(0,16);ctx.lineTo(-13,0);ctx.closePath();ctx.stroke();ctx.fillStyle='#d4ff48';ctx.fillRect(-2,-2,4,4);ctx.restore();ctx.strokeStyle='#839878';ctx.globalAlpha=.35;ctx.beginPath();ctx.moveTo(n.x,n.y+22);ctx.lineTo(n.x,n.y+58);ctx.stroke();ctx.globalAlpha=1}
 // enemies
 for(const e of enemies)if(e.hp>0)drawDrone(e);
 if(nodes.every(n=>n.got))drawBoss();
 // bullets and plasma
 for(const b of bullets){ctx.save();ctx.shadowBlur=14;ctx.shadowColor=b.from==='player'?'#d4ff48':'#ff514c';ctx.fillStyle=b.from==='player'?'#efffb0':'#ff685b';ctx.beginPath();ctx.ellipse(b.x,b.y,b.from==='player'?7:6,3,0,0,Math.PI*2);ctx.fill();ctx.restore()}
 // player flashlight beam
 let px=player.x+12,py=player.y+20;ctx.save();ctx.globalAlpha=.14;let cone=ctx.createLinearGradient(px,py,px+player.face*330,py+55);cone.addColorStop(0,'#e1f4bd');cone.addColorStop(1,'#c7e69800');ctx.fillStyle=cone;ctx.beginPath();ctx.moveTo(px,py-5);ctx.lineTo(px+player.face*340,py-82);ctx.lineTo(px+player.face*340,py+110);ctx.closePath();ctx.fill();ctx.restore();drawPlayer();
 // particles
 for(const a of particles){ctx.globalAlpha=clamp(a.life/a.max,0,1);ctx.fillStyle=a.color;ctx.fillRect(a.x,a.y,a.size,a.size)}ctx.globalAlpha=1;
 ctx.restore();
 // atmospheric haze/vignette and edge meter
 const fog=ctx.createLinearGradient(0,300,0,540);fog.addColorStop(0,'#10191a00');fog.addColorStop(1,'#05090bd9');ctx.fillStyle=fog;ctx.fillRect(0,300,W,240);
 if(mode==='play'&&player.x>3420&&!nodes.every(n=>n.got)){ctx.fillStyle='#080d10cf';ctx.fillRect(0,0,W,H);ctx.fillStyle='#dce7dc';ctx.font='600 15px monospace';ctx.textAlign='center';ctx.fillText('THREE SIGNAL NODES REQUIRED',W/2,H/2)}
 if(mode==='play'&&nodes.every(n=>n.got)&&player.x>3350){ctx.fillStyle='#ff554f';ctx.globalAlpha=.04+Math.sin(tick*8)*.025;ctx.fillRect(0,0,W,H);ctx.globalAlpha=1}
}

